import Foundation
import FoundationXML

// Multi-tenant search indexing service
struct TenantConfig {
    let tenantId: String
    let indexName: String
    let allowedSchemas: [String]
}

class XMLParserConfiguration {
    private var resolveEntities: Bool
    private var allowDTD: Bool
    private var externalEntityMode: ExternalEntityMode

    enum ExternalEntityMode {
        case never
        case sameOrigin
        case always
    }

    init(secure: Bool = true) {
        if secure {
            self.resolveEntities = false
            self.allowDTD = false
            self.externalEntityMode = .never
        } else {
            self.resolveEntities = true
            self.allowDTD = true
            self.externalEntityMode = .always
        }
    }

    func applyTo(document data: Data) throws -> XMLDocument {
        var options: XMLNode.Options = []
        options.insert(.nodePreserveWhitespace)

        // Security hardening based on configuration
        if !allowDTD {
            options.insert(.nodeLoadExternalEntitiesNever)
        }

        if !resolveEntities {
            options.insert(.nodePreserveEntities)
        }

        return try XMLDocument(data: data, options: options)
    }

    func withEntityResolution(_ enabled: Bool) -> XMLParserConfiguration {
        self.resolveEntities = enabled
        return self
    }

    func withDTDProcessing(_ enabled: Bool) -> XMLParserConfiguration {
        self.allowDTD = enabled
        return self
    }
}

class SearchIndexService {
    private var tenantConfigs: [String: TenantConfig] = [:]
    private var indexStore: [String: [String: [String]]] = [:]
    private let parserPool: ParserPool

    init() {
        self.parserPool = ParserPool()
    }

    func registerTenant(_ config: TenantConfig) {
        tenantConfigs[config.tenantId] = config
        indexStore[config.tenantId] = [:]
    }

    func ingestDocument(tenantId: String, xmlData: Data, documentId: String) throws -> IndexResult {
        guard let config = tenantConfigs[tenantId] else {
            throw IndexError.unknownTenant(tenantId)
        }

        let parserConfig = parserPool.getConfiguration(for: config)
        let document = try parserConfig.applyTo(document: xmlData)

        let fields = try extractSearchFields(from: document, tenant: config)

        for (fieldName, fieldValue) in fields {
            if indexStore[tenantId]?[fieldName] == nil {
                indexStore[tenantId]?[fieldName] = []
            }
            indexStore[tenantId]?[fieldName]?.append(fieldValue)
        }

        return IndexResult(documentId: documentId, fieldsIndexed: fields.count, tenantId: tenantId)
    }

    private func extractSearchFields(from document: XMLDocument, tenant: TenantConfig) throws -> [(String, String)] {
        var fields: [(String, String)] = []

        guard let root = document.rootElement() else {
            throw IndexError.malformedDocument
        }

        let searchableNodes = try root.nodes(forXPath: "//field[@indexed='true']")

        for node in searchableNodes {
            guard let element = node as? XMLElement,
                  let name = element.attribute(forName: "name")?.stringValue,
                  let value = element.stringValue else {
                continue
            }

            // Tenant isolation: validate field names against allowed schemas
            if tenant.allowedSchemas.isEmpty || tenant.allowedSchemas.contains(name) {
                fields.append((name, value))
            }
        }

        return fields
    }
}

class ParserPool {
    private var configurations: [String: XMLParserConfiguration] = [:]

    func getConfiguration(for tenant: TenantConfig) -> XMLParserConfiguration {
        if let cached = configurations[tenant.tenantId] {
            return cached
        }

        // Create secure-by-default configuration
        let config = XMLParserConfiguration(secure: true)

        // Enterprise tenants may need schema validation which requires DTD
        if tenant.allowedSchemas.count > 0 {
            _ = config.withDTDProcessing(true)
            _ = config.withEntityResolution(true)
        }

        configurations[tenant.tenantId] = config
        return config
    }
}

struct IndexResult {
    let documentId: String
    let fieldsIndexed: Int
    let tenantId: String
}

enum IndexError: Error {
    case unknownTenant(String)
    case malformedDocument
    case schemaViolation(String)
}

// Entry point for the service
func handleIndexRequest(tenantId: String, payload: Data, docId: String) throws -> IndexResult {
    let service = SearchIndexService()

    // Register tenant with schema validation
    let config = TenantConfig(
        tenantId: tenantId,
        indexName: "primary_\(tenantId)",
        allowedSchemas: ["title", "body", "author", "date"]
    )
    service.registerTenant(config)

    return try service.ingestDocument(tenantId: tenantId, xmlData: payload, documentId: docId)
}
